/* eslint-disable @next/next/no-img-element -- project media URLs are supplied by an external CDN. */

import type { WorkProject } from "../work.types";
import styles from "../WorkPage.module.css";

interface ProjectCardProps {
  project: WorkProject;
  index: number;
  onOpen: (project: WorkProject) => void;
}

export default function ProjectCard({ project, index, onOpen }: ProjectCardProps) {
  const mediaCount = project.gallery.length;

  return (
    <li className={styles.gridItem}>
      <a
        className={`page-card glass-panel ${styles.projectCard}`}
        href={`/work/${encodeURIComponent(project.slug)}`}
        aria-label={`View ${project.title} project`}
        onClick={(event) => {
          // Let the browser handle new-tab / modified clicks.
          if (
            event.button !== 0 ||
            event.metaKey ||
            event.ctrlKey ||
            event.shiftKey ||
            event.altKey
          ) {
            return;
          }
          event.preventDefault();
          onOpen(project);
        }}
      >
        <span className={styles.cardCover}>
          <img
            src={project.cover}
            alt={`${project.title} project cover`}
            loading={index < 2 ? "eager" : "lazy"}
            fetchPriority={index < 2 ? "high" : "auto"}
            decoding="async"
          />
        </span>
        <span className={styles.cardText}>
          <span className={styles.cardCategory}>{project.category}</span>
          <span className={styles.cardTitle}>{project.title}</span>
          {project.description && <span className={styles.cardDesc}>{project.description}</span>}
          <span className={styles.cardFooter}>
            <span className={styles.cardMeta}>
              {mediaCount > 0 ? `${mediaCount} ${mediaCount === 1 ? "item" : "items"}` : "Case study"}
            </span>
            <span className={styles.cardCta}>
              View project <span aria-hidden="true">↗</span>
            </span>
          </span>
        </span>
      </a>
    </li>
  );
}
