import { useCallback, useMemo, useState } from "react";
import type { WorkProject } from "./work.types";
import { getCategories } from "./work-utils";

export const ALL = "All";
const BATCH_SIZE = 24;

/**
 * Filter + "load more" state for the listing.
 * It lives in WorkPage (not WorkListing) so the chosen filter survives
 * opening a project and coming back.
 */
export function useWorkListing(allProjects: WorkProject[]) {
  const [activeFilter, setActiveFilter] = useState<string>(ALL);
  const [visibleCount, setVisibleCount] = useState(BATCH_SIZE);

  const categories = useMemo(() => getCategories(allProjects), [allProjects]);

  const filtered = useMemo(
    () =>
      activeFilter === ALL
        ? allProjects
        : allProjects.filter((project) => project.category === activeFilter),
    [allProjects, activeFilter],
  );

  const selectFilter = useCallback((value: string) => {
    setActiveFilter(value);
    setVisibleCount(BATCH_SIZE);
  }, []);

  const total = filtered.length;
  const showMore = useCallback(
    () => setVisibleCount((count) => Math.min(count + BATCH_SIZE, total)),
    [total],
  );

  return {
    activeFilter,
    selectFilter,
    categories,
    allCount: allProjects.length,
    projects: filtered.slice(0, visibleCount),
    total,
    hasMore: visibleCount < total,
    showMore,
  };
}

export type WorkListingState = ReturnType<typeof useWorkListing>;
