import { ALL } from "../useWorkListing";
import styles from "../WorkPage.module.css";

interface CategoryFilterProps {
  categories: string[];
  active: string;
  onSelect: (category: string) => void;
}

export default function CategoryFilter({ categories, active, onSelect }: CategoryFilterProps) {
  return (
    <ul className={styles.filters} aria-label="Filter work by category">
      {[ALL, ...categories].map((category) => (
        <li key={category}>
          <button
            type="button"
            className={`${styles.filterBtn}${active === category ? ` ${styles.filterActive}` : ""}`}
            aria-pressed={active === category}
            onClick={() => onSelect(category)}
          >
            {category}
          </button>
        </li>
      ))}
    </ul>
  );
}
