/* eslint-disable @next/next/no-img-element -- project media URLs are supplied by an external CDN. */

import type { WorkMedia, WorkProject } from "../work.types";
import { getYouTubeId, getYouTubeThumbnail } from "../work-utils";
import styles from "../WorkPage.module.css";

interface MediaThumbnailProps {
  media: WorkMedia;
  project: WorkProject;
  index: number;
  onOpen: (index: number) => void;
}

export default function MediaThumbnail({ media, project, index, onOpen }: MediaThumbnailProps) {
  const isVideo = media.type === "video" || media.type === "youtube";
  const label = isVideo
    ? `Open video ${index + 1} from ${project.title}`
    : `Open image ${index + 1} from ${project.title}`;

  let posterSrc: string | undefined;
  if (media.type === "video") {
    posterSrc = media.poster;
  } else if (media.type === "youtube") {
    const id = getYouTubeId(media.url);
    posterSrc = media.poster ?? (id ? getYouTubeThumbnail(id) : undefined);
  }

  return (
    <li className={styles.galleryItem}>
      <button
        type="button"
        className={styles.galleryButton}
        aria-label={label}
        onClick={() => onOpen(index)}
      >
        {media.type === "image" ? (
          <img
            className={styles.galleryImage}
            src={media.url}
            alt={media.alt || `${project.title} project image ${index + 1}`}
            loading="lazy"
            decoding="async"
          />
        ) : posterSrc ? (
          <img
            className={styles.galleryImage}
            src={posterSrc}
            alt=""
            loading="lazy"
            decoding="async"
          />
        ) : (
          <span className={styles.videoPlaceholder} aria-hidden="true" />
        )}
        {isVideo && (
          <span className={styles.videoMark} aria-hidden="true">
            ▶
          </span>
        )}
      </button>
    </li>
  );
}
