"use client";

import { notFound, usePathname, useRouter } from "next/navigation";
import { useCallback, useEffect, useMemo, useRef, type MouseEvent } from "react";
import { PageShell } from "~/components/PageLayout/PageLayout";
import ProjectDetail from "./components/ProjectDetail";
import WorkListing from "./components/WorkListing";
import { useWorkListing } from "./useWorkListing";
import type { WorkProject } from "./work.types";
import { buildStats, getProjectSlug, normalizePath } from "./work-utils";
import styles from "./WorkPage.module.css";

interface WorkPageProps {
  projects: WorkProject[];
}

export default function WorkPage({ projects }: WorkPageProps) {
  const router = useRouter();
  const routePathname = usePathname();
  const listing = useWorkListing(projects);
  const stats = useMemo(() => buildStats(projects), [projects]);

  // Derived from the router path, so the prerendered HTML already contains the right page.
  const pathname = normalizePath(routePathname || "/work");
  const slug = getProjectSlug(pathname);
  const isMalformedPath = pathname !== "/work" && slug === null;
  const project = useMemo(
    () => (slug ? (projects.find((entry) => entry.slug === slug) ?? null) : null),
    [slug, projects],
  );

  const previousPathname = useRef<string | null>(null);
  const enteredFromListing = useRef(false);

  // Restore the listing scroll position after returning from a project.
  useEffect(() => {
    const previous = previousPathname.current;
    previousPathname.current = pathname;

    if (previous?.startsWith("/work/") && pathname === "/work") {
      const scrollY = Number(window.history.state?.workScrollY) || 0;
      window.requestAnimationFrame(() => window.scrollTo(0, scrollY));
    }
  }, [pathname]);

  useEffect(() => {
    const previousTitle = document.title;
    document.title = project ? `${project.title} | Work | Pinktra` : "Work | Pinktra";
    return () => {
      document.title = previousTitle;
    };
  }, [project]);

  const openProject = useCallback(
    (selected: WorkProject) => {
      window.history.replaceState(
        { ...(window.history.state ?? {}), workScrollY: window.scrollY },
        "",
        window.location.href,
      );
      enteredFromListing.current = true;
      router.push(`/work/${encodeURIComponent(selected.slug)}`, { scroll: false });
      window.scrollTo(0, 0);
    },
    [router],
  );

  const returnToListing = useCallback(
    (event: MouseEvent<HTMLAnchorElement>) => {
      event.preventDefault();
      if (enteredFromListing.current) {
        router.back();
      } else {
        router.push("/work", { scroll: false });
      }
    },
    [router],
  );

  // Unknown project or malformed URL: show the site's not-found page.
  // Kept after all hooks so hook order never changes.
  if (isMalformedPath || (slug && !project)) {
    notFound();
  }

  return (
    <PageShell className={styles.workPage}>
      <main className={`app-container page-container ${styles.workContainer}`}>
        {project ? (
          <ProjectDetail project={project} onBack={returnToListing} />
        ) : (
          <WorkListing listing={listing} onOpenProject={openProject} stats={stats} />
        )}
      </main>
    </PageShell>
  );
}