"use client";
/* eslint-disable @next/next/no-img-element -- project media URLs are supplied by an external CDN. */

import CloseIcon from "@mui/icons-material/Close";
import NavigateBeforeIcon from "@mui/icons-material/NavigateBefore";
import NavigateNextIcon from "@mui/icons-material/NavigateNext";
import RestartAltIcon from "@mui/icons-material/RestartAlt";
import RotateRightIcon from "@mui/icons-material/RotateRight";
import ZoomInIcon from "@mui/icons-material/ZoomIn";
import ZoomOutIcon from "@mui/icons-material/ZoomOut";
import { useCallback, useEffect, useRef, useState, type PointerEvent } from "react";
import type { WorkMedia } from "../work.types";
import { getYouTubeEmbedUrl, getYouTubeId } from "../work-utils";
import styles from "../WorkPage.module.css";

const MIN_ZOOM = 1;
const MAX_ZOOM = 4;
const BUTTON_STEP = 0.5;
const WHEEL_STEP = 0.25;

interface MediaLightboxProps {
  media: WorkMedia[];
  index: number;
  projectTitle: string;
  onClose: () => void;
  onNavigate: (index: number) => void;
}

const clampZoom = (value: number) =>
  Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, Math.round(value * 100) / 100));

export default function MediaLightbox({
  media,
  index,
  projectTitle,
  onClose,
  onNavigate,
}: MediaLightboxProps) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const closeButtonRef = useRef<HTMLButtonElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const touchStartX = useRef<number | null>(null);
  const sizes = useRef({ stageW: 0, stageH: 0, imgW: 0, imgH: 0 });
  const drag = useRef<{ startX: number; startY: number; originX: number; originY: number } | null>(
    null,
  );
  const activeMedia = media[index];
  const isImage = activeMedia?.type === "image";

  // Image transform state. `rotation` keeps growing (90, 180, 270, 360...) so the animation
  // always turns clockwise. `fit` shrinks a sideways image so it still fits the screen.
  const [zoom, setZoom] = useState(MIN_ZOOM);
  const [rotation, setRotation] = useState(0);
  const [fit, setFit] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);

  const isSideways = rotation % 180 !== 0;
  const scale = zoom * fit;

  /** Keeps the zoomed image from being dragged out of view. */
  const clampOffset = useCallback(
    (x: number, y: number, nextScale: number, sideways: boolean) => {
      const { stageW, stageH, imgW, imgH } = sizes.current;
      const visualW = (sideways ? imgH : imgW) * nextScale;
      const visualH = (sideways ? imgW : imgH) * nextScale;
      const maxX = Math.max(0, (visualW - stageW) / 2);
      const maxY = Math.max(0, (visualH - stageH) / 2);
      return {
        x: Math.min(maxX, Math.max(-maxX, x)),
        y: Math.min(maxY, Math.max(-maxY, y)),
      };
    },
    [],
  );

  const measure = useCallback(() => {
    const stage = stageRef.current;
    const image = imageRef.current;
    if (!stage || !image) return;

    const stageW = stage.clientWidth;
    const stageH = stage.clientHeight;
    const imgW = image.offsetWidth;
    const imgH = image.offsetHeight;
    sizes.current = { stageW, stageH, imgW, imgH };

    setFit(
      rotation % 180 !== 0 && imgW > 0 && imgH > 0
        ? Math.min(stageW / imgH, stageH / imgW, 1)
        : 1,
    );
  }, [rotation]);

  const applyZoom = useCallback(
    (next: number) => {
      const value = clampZoom(next);
      setZoom(value);
      setOffset((current) =>
        value <= MIN_ZOOM ? { x: 0, y: 0 } : clampOffset(current.x, current.y, value * fit, isSideways),
      );
    },
    [clampOffset, fit, isSideways],
  );

  const rotate = useCallback(() => {
    setRotation((current) => current + 90);
    setOffset({ x: 0, y: 0 });
  }, []);

  const resetView = useCallback(() => {
    setZoom(MIN_ZOOM);
    setOffset({ x: 0, y: 0 });
    // Finish the current turn instead of spinning back.
    setRotation((current) => Math.ceil(current / 360) * 360);
  }, []);

  // New media: start from the default view.
  useEffect(() => {
    setZoom(MIN_ZOOM);
    setRotation(0);
    setFit(1);
    setOffset({ x: 0, y: 0 });
  }, [index]);

  // Re-measure when the rotation changes or the window is resized.
  useEffect(() => {
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, [measure, index]);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        onClose();
      } else if (event.key === "ArrowLeft" && media.length > 1) {
        event.preventDefault();
        onNavigate((index - 1 + media.length) % media.length);
      } else if (event.key === "ArrowRight" && media.length > 1) {
        event.preventDefault();
        onNavigate((index + 1) % media.length);
      } else if (isImage) {
        if (event.key === "+" || event.key === "=") {
          event.preventDefault();
          applyZoom(zoom + BUTTON_STEP);
        } else if (event.key === "-" || event.key === "_") {
          event.preventDefault();
          applyZoom(zoom - BUTTON_STEP);
        } else if (event.key === "r" || event.key === "R") {
          event.preventDefault();
          rotate();
        } else if (event.key === "0") {
          event.preventDefault();
          resetView();
        }
      }
    },
    [index, media.length, onClose, onNavigate, isImage, zoom, applyZoom, rotate, resetView],
  );

  // Open as a modal, lock page scroll, and restore focus on close.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;

    const previousFocus = document.activeElement;
    const previousOverflow = document.body.style.overflow;
    if (!dialog.open) dialog.showModal();
    document.body.style.overflow = "hidden";
    dialog.focus();

    return () => {
      if (dialog.open) dialog.close();
      document.body.style.overflow = previousOverflow;
      if (previousFocus instanceof HTMLElement && previousFocus.isConnected) {
        previousFocus.focus();
      }
    };
  }, []);

  useEffect(() => {
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  if (!activeMedia) return null;

  const navigateBy = (offsetBy: number) => {
    onNavigate((index + offsetBy + media.length) % media.length);
  };

  const canPan = isImage && zoom > MIN_ZOOM;
  const isDefaultView = zoom === MIN_ZOOM && rotation % 360 === 0;

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (!canPan) return;
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = {
      startX: event.clientX,
      startY: event.clientY,
      originX: offset.x,
      originY: offset.y,
    };
    setDragging(true);
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const current = drag.current;
    if (!current) return;
    setOffset(
      clampOffset(
        current.originX + event.clientX - current.startX,
        current.originY + event.clientY - current.startY,
        scale,
        isSideways,
      ),
    );
  };

  const endDrag = () => {
    drag.current = null;
    setDragging(false);
  };

  const stageClassName = [styles.lightboxStage, canPan ? styles.lightboxStagePan : ""]
    .filter(Boolean)
    .join(" ");

  const imageClassName = [styles.lightboxImage, dragging ? styles.lightboxImageDragging : ""]
    .filter(Boolean)
    .join(" ");

  return (
    <dialog
      ref={dialogRef}
      className={styles.lightbox}
      tabIndex={-1}
      aria-label={`${projectTitle} media viewer`}
      onCancel={(event) => {
        event.preventDefault();
        onClose();
      }}
    >
      <div className={styles.lightboxShell}>
        <div className={styles.lightboxControls}>
          <span className={styles.lightboxCounter} aria-live="polite">
            {index + 1} / {media.length}
          </span>

          {isImage && (
            <div className={styles.lightboxTools} role="group" aria-label="Image tools">
              <button
                type="button"
                className={styles.lightboxTool}
                aria-label="Zoom out"
                title="Zoom out (-)"
                disabled={zoom <= MIN_ZOOM}
                onClick={() => applyZoom(zoom - BUTTON_STEP)}
              >
                <ZoomOutIcon aria-hidden="true" />
              </button>
              <span className={styles.lightboxZoomLabel} aria-live="polite">
                {Math.round(zoom * 100)}%
              </span>
              <button
                type="button"
                className={styles.lightboxTool}
                aria-label="Zoom in"
                title="Zoom in (+)"
                disabled={zoom >= MAX_ZOOM}
                onClick={() => applyZoom(zoom + BUTTON_STEP)}
              >
                <ZoomInIcon aria-hidden="true" />
              </button>
              <span className={styles.lightboxDivider} aria-hidden="true" />
              <button
                type="button"
                className={styles.lightboxTool}
                aria-label="Rotate image"
                title="Rotate (R)"
                onClick={rotate}
              >
                <RotateRightIcon aria-hidden="true" />
              </button>
              <button
                type="button"
                className={styles.lightboxTool}
                aria-label="Reset zoom and rotation"
                title="Reset (0)"
                disabled={isDefaultView}
                onClick={resetView}
              >
                <RestartAltIcon aria-hidden="true" />
              </button>
            </div>
          )}

          <button
            ref={closeButtonRef}
            type="button"
            className={styles.lightboxButton}
            aria-label="Close media viewer"
            onClick={onClose}
          >
            <CloseIcon aria-hidden="true" />
          </button>
        </div>

        <div
          ref={stageRef}
          className={stageClassName}
          onTouchStart={(event) => {
            // Swiping changes media only at normal zoom; when zoomed, dragging pans instead.
            touchStartX.current =
              isImage && zoom === MIN_ZOOM ? (event.touches[0]?.clientX ?? null) : null;
          }}
          onTouchEnd={(event) => {
            const startX = touchStartX.current;
            const endX = event.changedTouches[0]?.clientX;
            touchStartX.current = null;
            if (startX === null || endX === undefined || Math.abs(endX - startX) < 55) return;
            navigateBy(endX < startX ? 1 : -1);
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
          onWheel={(event) => {
            if (!isImage) return;
            applyZoom(zoom + (event.deltaY < 0 ? WHEEL_STEP : -WHEEL_STEP));
          }}
          onDoubleClick={() => {
            if (!isImage) return;
            if (zoom > MIN_ZOOM) applyZoom(MIN_ZOOM);
            else applyZoom(2);
          }}
        >
          {activeMedia.type === "image" ? (
            <img
              ref={imageRef}
              key={activeMedia.url}
              className={imageClassName}
              src={activeMedia.url}
              alt={activeMedia.alt || `${projectTitle} project image ${index + 1}`}
              draggable={false}
              onLoad={measure}
              style={{
                transform: `translate(${offset.x}px, ${offset.y}px) rotate(${rotation}deg) scale(${scale})`,
              }}
            />
          ) : activeMedia.type === "youtube" ? (
            (() => {
              const id = getYouTubeId(activeMedia.url);
              if (!id) return null;
              return (
                <iframe
                  key={id}
                  className={styles.lightboxYoutube}
                  src={getYouTubeEmbedUrl(id)}
                  title={activeMedia.title || `${projectTitle} video ${index + 1}`}
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen"
                  allowFullScreen
                  referrerPolicy="strict-origin-when-cross-origin"
                />
              );
            })()
          ) : (
            <video
              key={activeMedia.url}
              className={styles.lightboxVideo}
              src={activeMedia.url}
              poster={activeMedia.poster}
              autoPlay
              controls
              playsInline
              preload="metadata"
            >
              Your browser does not support HTML video.
            </video>
          )}
        </div>

        {media.length > 1 && (
          <div className={styles.lightboxNavigation}>
            <button
              type="button"
              className={styles.lightboxButton}
              aria-label="Previous media"
              onClick={() => navigateBy(-1)}
            >
              <NavigateBeforeIcon aria-hidden="true" />
            </button>
            <button
              type="button"
              className={styles.lightboxButton}
              aria-label="Next media"
              onClick={() => navigateBy(1)}
            >
              <NavigateNextIcon aria-hidden="true" />
            </button>
          </div>
        )}
      </div>
    </dialog>
  );
}
