"use client";

import { useEffect, useRef } from "react";
import { PageHeader } from "~/components/PageLayout/PageLayout";
import type { WorkListingState } from "../useWorkListing";
import type { WorkProject } from "../work.types";
import type { WorkStat } from "../work-content";
import styles from "../WorkPage.module.css";
import CategoryFilter from "./CategoryFilter";
import ProcessSection from "./ProcessSection";
import ProjectCard from "./ProjectCard";
import StatsStrip from "./StatsStrip";
import WorkCTA from "./WorkCTA";

interface WorkListingProps {
  listing: WorkListingState;
  onOpenProject: (project: WorkProject) => void;
  stats: WorkStat[];
}

export default function WorkListing({ listing, onOpenProject, stats }: WorkListingProps) {
  const { activeFilter, selectFilter, categories, allCount, projects, total, hasMore, showMore } =
    listing;
  const sentinelRef = useRef<HTMLDivElement>(null);

  // Load the next batch when the sentinel nears the viewport.
  useEffect(() => {
    if (!hasMore || !sentinelRef.current || typeof IntersectionObserver === "undefined") return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) showMore();
      },
      { rootMargin: "600px 0px" },
    );

    observer.observe(sentinelRef.current);
    return () => observer.disconnect();
  }, [hasMore, showMore, projects.length]);

  return (
    <>
      <PageHeader
        badge="Pinktra Work"
        title="Work We're Proud Of"
        description="Every website, application, product, and digital experience Pinktra has built for businesses, startups, and creators."
      />

      {allCount === 0 ? (
        <p className={styles.emptyState}>No work available yet.</p>
      ) : (
        <section className={styles.collection} aria-labelledby="work-collection-title">
          <h2 id="work-collection-title" className={styles.srOnly}>
            All work
          </h2>

          <StatsStrip stats={stats} />

          {categories.length > 1 && (
            <CategoryFilter
              categories={categories}
              active={activeFilter}
              onSelect={selectFilter}
            />
          )}

          {total === 0 ? (
            <p className={styles.emptyState}>No work in this category yet. Check back soon.</p>
          ) : (
            <ul className={styles.grid} aria-label="All projects">
              {projects.map((project, index) => (
                <ProjectCard
                  key={project.slug}
                  project={project}
                  index={index}
                  onOpen={onOpenProject}
                />
              ))}
            </ul>
          )}

          {hasMore && <div ref={sentinelRef} className={styles.sentinel} aria-hidden="true" />}

          <ProcessSection />

          <WorkCTA
            title="Have a project in mind?"
            description="Whether it's a website, an application, or a full product, Pinktra would love to help bring your idea to life."
          />
        </section>
      )}
    </>
  );
}
