import { createSlug } from "~/utils/slug";
import type { WorkProject, WorkProjectInput } from "./work.types";
import { START_YEAR, STATIC_STATS, type WorkStat } from "./work-content";
import { CURRENT_YEAR } from "~/utils/message";

export function normalizePath(pathname: string) {
  return pathname === "/" ? "/" : pathname.replace(/\/+$/, "");
}

export function getProjectSlug(pathname: string): string | null {
  const segments = normalizePath(pathname).split("/").filter(Boolean);
  if (segments.length !== 2 || segments[0] !== "work") return null;

  try {
    return decodeURIComponent(segments[1]);
  } catch {
    return segments[1];
  }
}

/**
 * Short, stable id (4 chars, e.g. "k3x9") made from a string.
 * It looks random but is the same on the server, in the browser and on every
 * build. Math.random() would give a different URL each time and break hydration.
 */
function shortId(value: string): string {
  let hash = 2166136261; // FNV-1a
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36).padStart(4, "0").slice(-4);
}

/**
 * Adds a slug (from the title) to every project.
 * The first project keeps the clean slug. If a later project would get the
 * same slug, a short id is added: "habit-tracker", "habit-tracker-k3x9".
 */
export function withSlugs(inputs: WorkProjectInput[]): WorkProject[] {
  const used = new Set<string>();

  return inputs.map((project, index) => {
    const base = createSlug(project.title);
    let slug = base;

    for (let attempt = 0; used.has(slug); attempt++) {
      slug = `${base}-${shortId(`${base}:${index}:${attempt}`)}`;
    }

    used.add(slug);
    return { ...project, slug };
  });
}

const YOUTUBE_ID = /^[\w-]{11}$/;

/**
 * Pulls the video id out of any common YouTube link
 * (watch?v=, youtu.be/, /shorts/, /embed/, /live/) or accepts a bare id.
 * Returns null when it isn't a YouTube link.
 */
export function getYouTubeId(input: string): string | null {
  const value = input.trim();
  if (YOUTUBE_ID.test(value)) return value;

  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return null;
  }

  const host = url.hostname.replace(/^(www|m|music)\./, "");
  let id: string | null = null;

  if (host === "youtu.be") {
    id = url.pathname.split("/")[1] ?? null;
  } else if (host === "youtube.com" || host === "youtube-nocookie.com") {
    if (url.pathname === "/watch") {
      id = url.searchParams.get("v");
    } else {
      const [kind, videoId] = url.pathname.split("/").filter(Boolean);
      if (kind === "embed" || kind === "shorts" || kind === "live" || kind === "v") id = videoId ?? null;
    }
  }

  return id && YOUTUBE_ID.test(id) ? id : null;
}

export function getYouTubeThumbnail(id: string): string {
  return `https://i.ytimg.com/vi/${id}/hqdefault.jpg`;
}

export function getYouTubeEmbedUrl(id: string): string {
  return `https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&modestbranding=1&playsinline=1`;
}

/** Unique categories, in the order they first appear. */
export function getCategories(projects: WorkProject[]): string[] {
  return Array.from(new Set(projects.map((project) => project.category)));
}


/** Builds the stats strip, with delivered projects and happy clients (one per project) counted from the fetched JSON. */
export function buildStats(projects: WorkProject[]): WorkStat[] {
  return [
    { value: CURRENT_YEAR - START_YEAR, suffix: "+", label: "Years of experience" },
    { value: projects.length, label: "Projects delivered" },
    { value: projects.length, label: "Happy clients" },
    STATIC_STATS.technologies,
  ];
}
