"use client";
/* eslint-disable @next/next/no-img-element -- project media URLs are supplied by an external CDN. */

import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { useCallback, useState, type MouseEvent } from "react";
import { PageHeader } from "~/components/PageLayout/PageLayout";
import type { WorkProject } from "../work.types";
import styles from "../WorkPage.module.css";
import MediaLightbox from "./MediaLightbox";
import MediaThumbnail from "./MediaThumbnail";
import WorkCTA from "./WorkCTA";

interface ProjectDetailProps {
  project: WorkProject;
  onBack: (event: MouseEvent<HTMLAnchorElement>) => void;
}

export default function ProjectDetail({ project, onBack }: ProjectDetailProps) {
  const [activeMediaIndex, setActiveMediaIndex] = useState<number | null>(null);
  const closeMedia = useCallback(() => setActiveMediaIndex(null), []);

  return (
    <>
      <a className={styles.backLink} href="/work" onClick={onBack}>
        <ArrowBackIcon aria-hidden="true" />
        All work
      </a>

      <PageHeader
        badge={project.category}
        title={project.title}
        description={project.description || "A digital experience built by Pinktra."}
        className={styles.projectHeader}
      />

      <figure className={styles.projectCover}>
        <img
          src={project.cover}
          alt={`${project.title} project cover`}
          fetchPriority="high"
          decoding="async"
        />
      </figure>

      {project.gallery.length > 0 && (
        <section className={styles.gallerySection} aria-label={`${project.title} gallery`}>
          <p className={styles.eyebrow}>Gallery</p>
          <h2 className={styles.sectionTitle}>Project gallery</h2>
          <ul className={styles.galleryGrid}>
            {project.gallery.map((media, index) => (
              <MediaThumbnail
                key={`${media.type}-${media.url}-${index}`}
                media={media}
                project={project}
                index={index}
                onOpen={setActiveMediaIndex}
              />
            ))}
          </ul>
        </section>
      )}

      {project.feedback && (
        <figure className={`glass-panel ${styles.feedback}`}>
          <p className={styles.eyebrow}>Client feedback</p>
          <blockquote>“{project.feedback.quote}”</blockquote>
          {project.feedback.author && <figcaption>{project.feedback.author}</figcaption>}
        </figure>
      )}

      <WorkCTA
        title="Want something like this?"
        description="Tell us about your idea and Pinktra will help you turn it into a polished, high-performing product."
      />

      {activeMediaIndex !== null && (
        <MediaLightbox
          media={project.gallery}
          index={activeMediaIndex}
          projectTitle={project.title}
          onClose={closeMedia}
          onNavigate={setActiveMediaIndex}
        />
      )}
    </>
  );
}
